#define GCREG_AHBXTTD_MISC_ReadMask                                   0xFF9FFFFC
#define GCREG_AHBXTTD_MISC_WriteMask                                  0xFFFE01FF
#define GCREG_AHBXTTD_MISC_ResetValue                                 0xFF000040

/* Write 1 to indicate the X-DMA shadow registers are all prepared,  and      **
** should be taken as the new walking pattern at the next frame start.        */
#define GCREG_AHBXTTD_MISC_XSHADOW_REG_PREPARED                              0:0
#define GCREG_AHBXTTD_MISC_XSHADOW_REG_PREPARED_End                            0
#define GCREG_AHBXTTD_MISC_XSHADOW_REG_PREPARED_Start                          0
#define GCREG_AHBXTTD_MISC_XSHADOW_REG_PREPARED_Type                         U01

/* Write 1 to perform a system level X-DMA software frame start.  Walker with **
** Walking_start_control == 2 will be started by this write.                  */
#define GCREG_AHBXTTD_MISC_XSOFTWARE_FRAME_START                             1:1
#define GCREG_AHBXTTD_MISC_XSOFTWARE_FRAME_START_End                           1
#define GCREG_AHBXTTD_MISC_XSOFTWARE_FRAME_START_Start                         1
#define GCREG_AHBXTTD_MISC_XSOFTWARE_FRAME_START_Type                        U01

/* Each bit controls the clock gating of specific VIP clusters. 0 means all   **
** clusters are running.  This is for Top Level AHB only.  These bits set the **
** VIP0~3 clock gates. VIP4 and VIP5 are set with bits 5:4 in register        **
** gcregAHBXTTDMiscAppendix.                                                  */
#define GCREG_AHBXTTD_MISC_VIP_CLUSTER_CLOCK_GATE                            5:2
#define GCREG_AHBXTTD_MISC_VIP_CLUSTER_CLOCK_GATE_End                          5
#define GCREG_AHBXTTD_MISC_VIP_CLUSTER_CLOCK_GATE_Start                        2
#define GCREG_AHBXTTD_MISC_VIP_CLUSTER_CLOCK_GATE_Type                       U04

/* Top Level AHB. Software sets 1 to reset all logic of the X-DMA and VIP     **
** modules.  This is a AHB only register. It does not have a related state    **
** load define. It is not shadowed.                                           */
#define GCREG_AHBXTTD_MISC_SOFT_RESET                                        6:6
#define GCREG_AHBXTTD_MISC_SOFT_RESET_End                                      6
#define GCREG_AHBXTTD_MISC_SOFT_RESET_Start                                    6
#define GCREG_AHBXTTD_MISC_SOFT_RESET_Type                                   U01

/* Set 1 to bypass the DenoisePostProcess module.  Out = PSI Out 2.  */
#define GCREG_AHBXTTD_MISC_DENOISE_POST_PROCESS_BYPASS                       7:7
#define GCREG_AHBXTTD_MISC_DENOISE_POST_PROCESS_BYPASS_End                     7
#define GCREG_AHBXTTD_MISC_DENOISE_POST_PROCESS_BYPASS_Start                   7
#define GCREG_AHBXTTD_MISC_DENOISE_POST_PROCESS_BYPASS_Type                  U01

/* Set 1 to bypass the On-Chip Memory (OCM). PSI (Packet Stream Interface)    **
** input will get data directly from Producer without OCM.  This field is set **
** for one input of OCMBypass.  For dual SBI input, the other is in bit 2 in  **
** gcregAHBSWControlDualSBIInput.                                             */
#define GCREG_AHBXTTD_MISC_OCM_BYPASS                                        8:8
#define GCREG_AHBXTTD_MISC_OCM_BYPASS_End                                      8
#define GCREG_AHBXTTD_MISC_OCM_BYPASS_Start                                    8
#define GCREG_AHBXTTD_MISC_OCM_BYPASS_Type                                   U01

/* Shows the busy status of system level DMA.  Bit 9 for DMA5, bit 10 fro     **
** DMA6,..., Bit 14 for DMA10.  Bit 15 for MATRIX, MATRIX is for access OCM   **
** logic.  Bit 16 for DMA11, DMA11 is for DPP V500                            */
#define GCREG_AHBXTTD_MISC_XTENSOR_IO_BUSY                                  16:9
#define GCREG_AHBXTTD_MISC_XTENSOR_IO_BUSY_End                                16
