#define   GCREG_AHBXTTD_MISC_XTENSOR_IO_BUSY_DMA6                           0x02
#define   GCREG_AHBXTTD_MISC_XTENSOR_IO_BUSY_DMA7                           0x04
#define   GCREG_AHBXTTD_MISC_XTENSOR_IO_BUSY_DMA8                           0x08
#define   GCREG_AHBXTTD_MISC_XTENSOR_IO_BUSY_DMA9                           0x10
#define   GCREG_AHBXTTD_MISC_XTENSOR_IO_BUSY_DMA10                          0x20
#define   GCREG_AHBXTTD_MISC_XTENSOR_IO_BUSY_MATRIX                         0x40
#define   GCREG_AHBXTTD_MISC_XTENSOR_IO_BUSY_DMA11                          0x80

/* Default Quality of Service (QOS)  Used by all AXI accesses except SBI2PSI, **
** PSI2SBI, Compress2DDR and DDR2Decompress.                                  */
#define GCREG_AHBXTTD_MISC_DEFAULT_QOS                                     20:17
#define GCREG_AHBXTTD_MISC_DEFAULT_QOS_End                                    20
#define GCREG_AHBXTTD_MISC_DEFAULT_QOS_Start                                  17
#define GCREG_AHBXTTD_MISC_DEFAULT_QOS_Type                                  U04

