#define   GCREG_AHB_PATTERNS_COMPARE_CHECKSUM_RED_ENABLE                     0x1

/* When enabled, Green comparison occurs at frame completion. */
#define GCREG_AHB_PATTERNS_COMPARE_CHECKSUM_GREEN                            1:1
#define GCREG_AHB_PATTERNS_COMPARE_CHECKSUM_GREEN_End                          1
#define GCREG_AHB_PATTERNS_COMPARE_CHECKSUM_GREEN_Start                        1
