#define GCREG_AHB_PATTERNS_MISMATCH_CHECKSUM_RED_End                           3
#define GCREG_AHB_PATTERNS_MISMATCH_CHECKSUM_RED_Start                         3
#define GCREG_AHB_PATTERNS_MISMATCH_CHECKSUM_RED_Type                        U01

/* Mismatch in Green checksum comparison. Write 1 to clear.  */
