/* Register gcregAHBDenoisePostProcess **
** ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ */

/* AHB DenoisePostProcess Shadow Configuration Register.  */

#define gcregAHBDenoisePostProcessRegAddrs                                0x0B6A
#define GCREG_AHB_DENOISE_POST_PROCESS_Address                           0x02DA8
#define GCREG_AHB_DENOISE_POST_PROCESS_MSB                                    15
#define GCREG_AHB_DENOISE_POST_PROCESS_LSB                                     0
#define GCREG_AHB_DENOISE_POST_PROCESS_BLK                                     0
#define GCREG_AHB_DENOISE_POST_PROCESS_Count                                   1
#define GCREG_AHB_DENOISE_POST_PROCESS_FieldMask                      0x000003FF
#define GCREG_AHB_DENOISE_POST_PROCESS_ReadMask                       0x000003FF
#define GCREG_AHB_DENOISE_POST_PROCESS_WriteMask                      0x000003FF
#define GCREG_AHB_DENOISE_POST_PROCESS_ResetValue                     0x00000000

/* DenoisePostProcess Mask mode. 3 bits total:  DMA_SOURCE_MASK_BIT2, upper   **
** bit is bit 8 in this register.  0: Mask(3:0) = {4{DMA4(4)}} (V400          **
** compatible setting);  1: Mask(3:0) = DMA2(7:4);  2: Mask(3:0) = DMA4(7:4); **
**  3: Mask(3:0) = {4{DMA4(4)}}, NewMask = DMA4[5];.  4: Mask(3:0) =          **
** DMA4(7:4), NewMask = DMA4[8];  5~7  Unused.                                */
#define GCREG_AHB_DENOISE_POST_PROCESS_DMA_SOURCE_MASK                       1:0
#define GCREG_AHB_DENOISE_POST_PROCESS_DMA_SOURCE_MASK_End                     1
#define GCREG_AHB_DENOISE_POST_PROCESS_DMA_SOURCE_MASK_Start                   0
#define GCREG_AHB_DENOISE_POST_PROCESS_DMA_SOURCE_MASK_Type                  U02

/* DenoisePostProcess Bypass Multiplication Logic level.  0: Bypass           **
** DenoisePostProcess Level V400;  1: Bypass DenoisePostProcess Level V500.   */
#define GCREG_AHB_DENOISE_POST_PROCESS_ONE_SUB_MASK                          2:2
#define GCREG_AHB_DENOISE_POST_PROCESS_ONE_SUB_MASK_End                        2
#define GCREG_AHB_DENOISE_POST_PROCESS_ONE_SUB_MASK_Start                      2
#define GCREG_AHB_DENOISE_POST_PROCESS_ONE_SUB_MASK_Type                     U01

/* 1: Bypass the DenoisePostProcess module in V500.  Use gcregTTDMisc Bit[2]  **
** for DPP bypass in V400.  Out = PSI Out 2                                   */
#define GCREG_AHB_DENOISE_POST_PROCESS_BYPASS_V500                           3:3
#define GCREG_AHB_DENOISE_POST_PROCESS_BYPASS_V500_End                         3
#define GCREG_AHB_DENOISE_POST_PROCESS_BYPASS_V500_Start                       3
#define GCREG_AHB_DENOISE_POST_PROCESS_BYPASS_V500_Type                      U01

/* DMA2 format. 0: INT16; 1: UINT16.  */
#define GCREG_AHB_DENOISE_POST_PROCESS_DMA2_FORMAT                           4:4
#define GCREG_AHB_DENOISE_POST_PROCESS_DMA2_FORMAT_End                         4
#define GCREG_AHB_DENOISE_POST_PROCESS_DMA2_FORMAT_Start                       4
#define GCREG_AHB_DENOISE_POST_PROCESS_DMA2_FORMAT_Type                      U01

/* DMA3 format. 0: INT16; 1: UINT16.  */
#define GCREG_AHB_DENOISE_POST_PROCESS_DMA3_FORMAT                           5:5
#define GCREG_AHB_DENOISE_POST_PROCESS_DMA3_FORMAT_End                         5
#define GCREG_AHB_DENOISE_POST_PROCESS_DMA3_FORMAT_Start                       5
#define GCREG_AHB_DENOISE_POST_PROCESS_DMA3_FORMAT_Type                      U01

/* DMA4 format. 0: INT16; 1: UINT16.  */
#define GCREG_AHB_DENOISE_POST_PROCESS_DMA4_FORMAT                           6:6
#define GCREG_AHB_DENOISE_POST_PROCESS_DMA4_FORMAT_End                         6
#define GCREG_AHB_DENOISE_POST_PROCESS_DMA4_FORMAT_Start                       6
#define GCREG_AHB_DENOISE_POST_PROCESS_DMA4_FORMAT_Type                      U01

/* DPP output format. 0: INT16; 1: UINT16.  */
#define GCREG_AHB_DENOISE_POST_PROCESS_OUT_FORMAT                            7:7
#define GCREG_AHB_DENOISE_POST_PROCESS_OUT_FORMAT_End                          7
#define GCREG_AHB_DENOISE_POST_PROCESS_OUT_FORMAT_Start                        7
#define GCREG_AHB_DENOISE_POST_PROCESS_OUT_FORMAT_Type                       U01

/* DenoisePostProcess Mask mode upper bit 2.  Lower bits are in               **
** gcregAHBDenoisePostProcess[1:0].DMA_SOURCE_MASK  0: Mask(3:0) =            **
** {4{DMA4(4)}} (V400 compatible setting);  1: Mask(3:0) = DMA2(7:4);  2:     **
** Mask(3:0) = DMA4(7:4);  3: Mask(3:0) = {4{DMA4(4)}}, NewMask = DMA4[5];.   **
** 4: Mask(3:0) = DMA4(7:4), NewMask = DMA4[8];  5~7  Unused.                 */
#define GCREG_AHB_DENOISE_POST_PROCESS_DMA_SOURCE_MASK_BIT2                  8:8
#define GCREG_AHB_DENOISE_POST_PROCESS_DMA_SOURCE_MASK_BIT2_End                8
#define GCREG_AHB_DENOISE_POST_PROCESS_DMA_SOURCE_MASK_BIT2_Start              8
#define GCREG_AHB_DENOISE_POST_PROCESS_DMA_SOURCE_MASK_BIT2_Type             U01

/* Clip res mask output.  0: Don't clip;  1: Clip.  */
#define GCREG_AHB_DENOISE_POST_PROCESS_RES_MASK_CLIP                         9:9
#define GCREG_AHB_DENOISE_POST_PROCESS_RES_MASK_CLIP_End                       9
#define GCREG_AHB_DENOISE_POST_PROCESS_RES_MASK_CLIP_Start                     9
#define GCREG_AHB_DENOISE_POST_PROCESS_RES_MASK_CLIP_Type                    U01

